            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextDouble();
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static final Comparator<Point> BY_X = (a, b) -> {
        int cmp = Double.compare(a.x, b.x);
        if (cmp != 0) return cmp;
        return Double.compare(a.y, b.y);
    };

    static final Comparator<Point> BY_Y = (a, b) -> {
        int cmp = Double.compare(a.y, b.y);
        if (cmp != 0) return cmp;
        return Double.compare(a.x, b.x);
    };

    static double dist(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    static double closest(Point[] pts, Point[] temp, int left, int right) {
        int n = right - left;
        if (n <= 3) {
            double ans = Double.POSITIVE_INFINITY;
            for (int i = left; i < right; i++) {
                for (int j = i + 1; j < right; j++) {
                    ans = Math.min(ans, dist(pts[i], pts[j]));
                }
            }
            Arrays.sort(pts, left, right, BY_Y);
            return ans;
        }

        int mid = (left + right) >>> 1;
        double midX = pts[mid].x;

        double d1 = closest(pts, temp, left, mid);
        double d2 = closest(pts, temp, mid, right);
        double d = Math.min(d1, d2);

        // Merge by y
        int i = left, j = mid, k = left;
        while (i < mid && j < right) {
            if (BY_Y.compare(pts[i], pts[j]) <= 0) temp[k++] = pts[i++];
            else temp[k++] = pts[j++];
        }
        while (i < mid) temp[k++] = pts[i++];
        while (j < right) temp[k++] = pts[j++];
        for (i = left; i < right; i++) pts[i] = temp[i];

        // Build strip
        int stripSize = 0;
        for (i = left; i < right; i++) {
            if (Math.abs(pts[i].x - midX) < d) {
                temp[stripSize++] = pts[i];
            }
        }

        // Check only next few points in y-order
        for (i = 0; i < stripSize; i++) {
            for (j = i + 1; j < stripSize && (temp[j].y - temp[i].y) < d; j++) {
                d = Math.min(d, dist(temp[i], temp[j]));
            }
        }

        return d;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Point[] pts = new Point[n];
        for (int i = 0; i < n; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            pts[i] = new Point(x, y);
        }

        Arrays.sort(pts, BY_X);
        Point[] temp = new Point[n];
        double ans = closest(pts, temp, 0, n);

        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        out.printf(Locale.US, "%.6f%n", ans);
        out.flush();
    }
}

import sys
import math
from itertools import combinations

def dist(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2)

def brute_force(points):
    min_d = float('inf')
    n = len(points)
    for i in range(n):
        for j in range(i+1, n):
            d = dist(points[i], points[j])
            if d < min_d:
                min_d = d
    return min_d

def strip_closest(strip, d):
    min_d = d
    strip.sort(key=lambda p: p[1])
    n = len(strip)
    for i in range(n):
        j = i + 1
        while j < n and (strip[j][1] - strip[i][1]) < min_d:
            dd = dist(strip[i], strip[j])
            if dd < min_d:
                min_d = dd
            j += 1
    return min_d

def closest_pair_rec(points_sorted_x):
    n = len(points_sorted_x)
    if n <= 3:
        return brute_force(points_sorted_x)

    mid = n // 2
    mid_point = points_sorted_x[mid]

    left = points_sorted_x[:mid]
    right = points_sorted_x[mid:]

    d_left = closest_pair_rec(left)
    d_right = closest_pair_rec(right)

    d = min(d_left, d_right)

    # Build strip
    strip = []
    for p in points_sorted_x:
        if abs(p[0] - mid_point[0]) < d:
            strip.append(p)

    return min(d, strip_closest(strip, d))

def closest_pair(points):
    points_sorted_x = sorted(points, key=lambda p: p[0])
    return closest_pair_rec(points_sorted_x)

def main():
    input_data = sys.stdin.read().split()
    idx = 0

    # Try to read number of points first
    n = int(input_data[idx]); idx += 1

    points = []
    for _ in range(n):
        x = float(input_data[idx]); idx += 1
        y = float(input_data[idx]); idx += 1
        points.append((x, y))

    if n < 2:
        print("0.00")
        return

    result = closest_pair(points)
    print(f"{result:.6f}")

main()
